        // Record before-values
        uint ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();
        uint balBefore = address(c).balance;

        // Non-owner fallback call: increase depositsCount, but shouldn't change owner or balance
        c.fallback{value: 0}();

        // Read after-values
        uint ownerAfter = c.owner();
        uint depositsAfter = c.depositsCount();
        uint balAfter = address(c).balance;

        // The only state change from a fallback call is depositsCount increasing by 1
        assert(ownerAfter == ownerBefore && balAfter == balBefore && depositsAfter == depositsBefore + 1);
    }

    receive() external payable {}
}

